  "Your iPhone. An agent that can act.": "home.heroTitle",
  "让智能体，真正操作你的 iPhone。": "home.heroTitle",
  "讓智慧代理，實際操作你的 iPhone。": "home.heroTitle",
  "iPhone を操作できるエージェント。": "home.heroTitle",
  "Агент, который управляет вашим iPhone.": "home.heroTitle",
  "Ein Agent, der dein iPhone bedienen kann.": "home.heroTitle",
  "Un agent qui agit sur votre iPhone.": "home.heroTitle",
  "Un agente que puede actuar en tu iPhone.": "home.heroTitle",
  "A browser-based AI automation framework for iPhone and iPad. Observe the screen, plan across apps, and act through an ESP32 input bridge.": "home.subtitle",
  "在浏览器中运行的 iPhone / iPad AI 自动化框架。观察屏幕，规划跨 App 任务，通过 ESP32 输入桥完成操作。": "home.subtitle",
  "在瀏覽器執行的 iPhone / iPad AI 自動化框架。觀察螢幕、規劃跨 App 任務，透過 ESP32 輸入橋完成操作。": "home.subtitle",
  "ブラウザで動く iPhone / iPad 向け AI 自動化フレームワーク。画面を観察し、アプリをまたぐタスクを計画して ESP32 入力ブリッジで操作します。": "home.subtitle",
  "Браузерная платформа AI-автоматизации для iPhone и iPad. Наблюдайте экран, планируйте задачи между приложениями и управляйте через мост ввода ESP32.": "home.subtitle",
  "Browserbasiertes KI-Automatisierungsframework für iPhone und iPad. Es beobachtet den Bildschirm, plant appübergreifend und bedient das Gerät über eine ESP32-Eingabebrücke.": "home.subtitle",
  "Un framework d’automatisation IA dans le navigateur pour iPhone et iPad. Il observe l’écran, planifie entre les apps et agit via un pont ESP32.": "home.subtitle",
  "Un framework de automatización con IA para iPhone y iPad en el navegador. Observa la pantalla, planifica entre apps y actúa mediante un puente ESP32.": "home.subtitle",
