  "システム画面から共有を開始し、画像で確認しながら上限付きの単一ポインター操作を実行します。": "home.featureScreenDescription",
  "Включите показ экрана через систему, затем выполняйте ограниченные действия одним указателем с проверкой по снимкам.": "home.featureScreenDescription",
