  "The phone and bridge need a reachable local network. Safari may request permission or block an insecure connection.": "device.networkHelp",
  "手机与设备需处于可互通的局域网。Safari 可能要求本地网络授权，或阻止不安全的连接。": "device.networkHelp",
  "手機與裝置須位於互通的區域網路。Safari 可能要求本機網路授權，或阻擋不安全的連線。": "device.networkHelp",
  "端末とブリッジは同じ到達可能なネットワークが必要です。Safari が許可を求めたり、安全でない接続を遮断する場合があります。": "device.networkHelp",
  "Телефон и мост должны быть доступны в локальной сети. Safari может запросить разрешение или заблокировать небезопасное соединение.": "device.networkHelp",
