  "Requires CORS. This check lists tools only: it does not execute them, add them to tasks or run stdio servers.": "mcp.help",
  "需要服务允许浏览器跨域访问。当前只诊断与读取目录，不执行工具，也不自动加入任务；不支持 stdio。": "mcp.help",
  "服務須允許跨來源存取。此處只診斷及讀取目錄，不執行工具、不自動加入任務，也不支援 stdio。": "mcp.help",
  "CORS が必要です。一覧のみ取得し、ツール実行、タスクへの追加、stdio サーバー起動は行いません。": "mcp.help",
  "Нужен CORS. Проверка только читает список: без выполнения, добавления в задачи и stdio.": "mcp.help",
  "CORS erforderlich. Die Prüfung listet nur Werkzeuge auf, ohne sie auszuführen oder stdio zu starten.": "mcp.help",
  "CORS requis. Ce diagnostic liste les outils sans les exécuter ni lancer stdio.": "mcp.help",
  "Requiere CORS. Solo se listan herramientas; no se ejecutan ni se inicia stdio.": "mcp.help",
